prts.feedbackvariables:
isValidVect(mat):=is(length(mat) = 4) and is(length(transpose(mat)) = 1);
isValidInput(lst):= if length(lst) = 5 then block(temp:map(isValidVect,lst), temp[1] and temp[2] and temp[3] and temp[4] and temp[5]) else false;
vectorEquiv(lst):=if isValidInput(lst) then lst else [matrix([0]),matrix([0]),matrix([0]),matrix([0]),matrix([0])];

pAns: vectorEquiv([ans1,ans2,ans3,ans4,ans5]);
if isValidInput(pAns)=false then pAns: vectorEquiv([ans1[1],ans2[1],ans3[1],ans4[1],ans5[1]]);
